[webgpu] Add getShader in WebGPUBackend

Currently this only supports webgpu backend.

Example code:
```
const conv2dSpec = {
  'name': 'conv2d',
  'inputs': [
    {'shape': [4, 4, 1], 'dtype': 'float32'},
    {'shape': [1, 1, 1, 3], 'dtype': 'float32'}
  ],
  'args': [[2, 2], 'same']
};

const addSpec = {
  'name': 'add',
  'inputs':
      [{'shape': [6], 'dtype': 'float32'}, {'shape': [6], 'dtype': 'float32'}]
};

const addSpec2 = {
  'name': 'add',
  'inputs': [{'shape': [6]}, {'shape': [6]}]
};
const sinSpec = {
  'name': 'sin',
  'inputs': [{'shape': [6], 'dtype': 'float32'}]
};

// Test get shader from single op.
function test1() {
  const shader = tf.backend().getShader(addSpec);
  printShader(shader);
}

// Test get shader from multiple ops.
function test2() {
  const inputSpecs = [];
  inputSpecs.push(conv2dSpec);
  inputSpecs.push(addSpec);
  inputSpecs.push(addSpec);
  inputSpecs.push(addSpec2);
  inputSpecs.push(sinSpec);
  const shader = tf.backend().getShader(inputSpecs);
  printShader(shader);
}

// Test get shader with user provided func.
function test3() {
  const shader = tf.backend().getShader(conv2dSpec, makeOp);
  printShader(shader);
}

function printShader(shader) {
  for (const key in shader) {
    console.group(key);
    console.debug(shader[key]);
    console.groupEnd();
  }
}

function makeOp(inputSpec) {
  const {name, inputs, args} = inputSpec;
  const tensorArray = [];
  inputs.forEach(input => {
    tensorArray.push(tf.zeros(input.shape, input.dtype));
  });
  try {
    if (typeof args === 'undefined') {
      tf[name](...tensorArray).dispose();
    } else {
      tf[name](...tensorArray, ...args).dispose();
    }
  } catch {
    throw new Error(`Operator ${name} is not defined in ${
        tf.engine().backendName} backend`);
  }

  tensorArray.forEach(tensor => {
    tensor.dispose();
  });
}

async function mainTest() {
  await tf.setBackend('webgpu');
  await tf.ready();
  if (typeof tf.backend().getShader === 'undefined') {
    throw new Error(
        `getShader is not defined in ${tf.engine().backendName} backend`);
  }
  test1();
  test2();
  test3();
}
```

